import { escapeHtml as h, number } from './domain.js';
const money=v=>`${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(Number(v)||0)} Þ`;
const time=v=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
const label=p=>`${p.name}${p.clan_name?` [${p.clan_name}]`:''}`;
const errorBox='<p class="form-error" role="alert" hidden></p>';
export function revenuesView(economy){
  if(!economy)return '<p class="empty">Chargement des finances…</p>';
  const totals=economy.planets.reduce((a,p)=>{for(const k of ['civil','trade','trade_cost','military','fleet','net'])a[k]=(a[k]||0)+Number(p[k]);return a;},{});
  return `<div class="economic-overview"><section class="balance-panel"><div class="eyebrow">TRÉSORERIE DISPONIBLE</div><div class="balance">${money(economy.treasury)}</div><p>${economy.enabled?`Prochain versement : <strong>${time(economy.next_payout_at)}</strong>`:'Activation économique en préparation.'}</p>${Number(economy.maintenance_debt)>0?`<p class="debt-note">Entretien à régulariser : ${money(economy.maintenance_debt)}. Les prochains revenus remboursent ce solde avant de reconstituer votre trésorerie.</p>`:''}</section><section class="daily-panel"><div class="eyebrow">SOLDE QUOTIDIEN</div><strong class="daily-net ${totals.net<0?'negative':''}">${totals.net>=0?'+':''}${money(totals.net)}</strong><p>Prévision avec vos populations, forces et liaisons actuelles. Le temps passé hors connexion est comptabilisé par le serveur.</p><button class="secondary" data-page="trade">Piloter le commerce →</button></section></div><section class="economic-table-section"><div class="section-heading"><h2>Revenus de vos mondes</h2><span>MONTANTS PAR JOUR</span></div><div class="economic-table-scroll"><table class="economic-table"><thead><tr><th>Planète</th><th>Revenus civils</th><th>Commerce brut + bonus</th><th>Entretien liaisons</th><th>Soldats</th><th>Vaisseaux</th><th>Solde</th></tr></thead><tbody>${economy.planets.map(p=>`<tr><th>${h(p.name)}</th><td>${money(p.civil)}</td><td>${money(p.trade)}</td><td class="expense">−${money(p.trade_cost)}</td><td class="expense">−${money(p.military)}</td><td class="expense">−${money(p.fleet)}</td><td class="net-cell ${Number(p.net)<0?'negative':''}">${money(p.net)}</td></tr>`).join('')}</tbody><tfoot><tr><th>Total</th><td>${money(totals.civil)}</td><td>${money(totals.trade)}</td><td>−${money(totals.trade_cost)}</td><td>−${money(totals.military)}</td><td>−${money(totals.fleet)}</td><td>${money(totals.net)}</td></tr></tfoot></table></div><p class="form-note">Le bonus Aurite de 15 % s’applique aux revenus civils et au rendement commercial après entretien des liaisons. Aucun coût industriel fictif n’est ajouté.</p></section><section class="payout-history"><div class="section-heading"><h2>Derniers versements</h2><span>TROIS FOIS PAR JOUR</span></div>${economy.history.length?`<ol>${economy.history.map(p=>`<li><time>${time(p.payout_at)}</time><span>${Number(p.net)>=0?'+':''}${money(p.net)}</span></li>`).join('')}</ol>`:'<p class="empty">Aucun versement depuis l’activation. Votre premier versement couvrira uniquement le temps réellement écoulé.</p>'}</section>`;
}
export function tradeView(data,planets,treasury,pending){
  if(!data)return '<div class="empty">Établissement des liaisons commerciales…</div>';
  const p=data.planet,available=p.capacity-p.occupied-p.reserved;
  return `<div class="trade-world-picker"><label class="field">Planète à gérer<select id="trade-world">${planets.map(w=>`<option value="${h(w.id)}" ${w.id===p.id?'selected':''}>${h(w.name)}</option>`).join('')}</select></label><div><strong>${p.occupied}<span> / ${p.capacity}</span></strong><small>CAPACITÉS OCCUPÉES</small></div><div><strong>${p.reserved}</strong><small>RÉSERVÉES EN ATTENTE</small></div><div><strong>${available}</strong><small>DISPONIBLES</small></div></div>${!data.enabled?'<p class="alpha-banner">L’économie est en cours de préparation. Les commandes seront disponibles après activation.</p>':''}${pending?`<section class="pending-command" role="status"><p>Une commande n’a pas reçu de confirmation. Reprenez-la avant d’en envoyer une autre pour éviter tout achat en double.</p><button id="resume-economic-command" class="secondary">Reprendre la commande</button><p class="form-error" hidden></p></section>`:''}<div class="trade-workbench"><section class="trade-purchase"><div class="eyebrow">DÉVELOPPEMENT COMMERCIAL</div><h2>Ouvrir de nouvelles routes.</h2><p>Construisez jusqu’à 200 capacités par monde. Une capacité occupée ne peut être utilisée par une autre liaison.</p>${data.prices.length?`<form id="buy-capacities"><label class="field">Capacités à construire<input name="quantity" type="number" min="1" max="${data.prices.length}" step="1" value="1" required></label><div class="purchase-quote"><span>Investissement</span><strong id="capacity-cost">${money(data.prices[0])}</strong></div><p class="form-note">Disponible : ${money(treasury)}. Construire une capacité ne crée pas automatiquement une liaison.</p>${errorBox}<button class="primary" type="submit" ${!data.enabled?'disabled':''}>Construire les capacités <span>→</span></button></form>`:'<p class="capacity-limit">Capacité maximale atteinte : 200.</p>'}</section><section class="trade-proposal"><div class="eyebrow">NOUVELLE LIAISON</div><h2>Relier deux mondes.</h2><p>Chaque liaison utilise la même quantité de capacités à ses deux extrémités et rapporte aux deux planètes.</p><form id="propose-trade"><label class="field">Destination<select name="target" required><option value="">Choisir un monde</option>${data.destinations.map(d=>`<option value="${h(d.id)}">${h(label(d))} · ${number(Math.round(d.distance))}</option>`).join('')}</select></label><label class="field">Capacités à engager<input name="quantity" type="number" min="1" max="${Math.max(1,available)}" step="1" value="1" required></label><div class="route-estimate" id="route-estimate">Choisissez une destination pour estimer le revenu de votre planète.</div><p class="form-note">L’ouverture est soumise aux capacités réellement disponibles à destination. L’identité et les informations stratégiques de ce monde restent masquées.</p>${errorBox}<button class="primary" type="submit" ${!data.enabled||available<1?'disabled':''}>Proposer la liaison <span>→</span></button></form></section></div><section class="trade-routes"><div class="section-heading"><h2>Vos liaisons</h2><span>${p.auto_trade?'ACCEPTATION AUTOMATIQUE':'VALIDATION MANUELLE'}</span></div><p class="form-note">${p.auto_trade?'Les nouvelles demandes entrantes sont acceptées automatiquement si les capacités sont disponibles.':'Examinez les demandes entrantes avant de les accepter.'} Une demande en attente réserve les capacités pendant 24 heures et ne rapporte rien.</p>${data.links.length?`<div class="routes-list">${data.links.map(l=>`<article class="trade-route"><div><span class="route-state ${l.status==='active'?'active':'pending'}">${l.status==='active'?'LIAISON ACTIVE':l.can_review?'DEMANDE À EXAMINER':'EN ATTENTE'}</span><h3>${h(label(l))}</h3><p>${l.quantity} capacités · distance ${number(Math.round(l.distance))}${l.expires_at?` · expiration ${time(l.expires_at)}`:''}</p></div><div class="route-profit"><strong>${l.status==='active'?'+':''}${money(l.net_daily)}<small> / jour</small></strong><span>${l.status==='active'?'Revenu net pour votre planète':'Revenu potentiel après acceptation'}</span></div><div class="route-actions">${l.can_review?`<button class="secondary" data-trade-action="accept" data-link="${h(l.id)}">Accepter</button><button class="text-button" data-trade-action="decline" data-link="${h(l.id)}">Refuser</button>`:`<button class="text-button" data-trade-action="cancel" data-link="${h(l.id)}">${l.status==='active'?'Fermer la liaison':'Retirer la demande'}</button>`}</div></article>`).join('')}</div>`:'<p class="empty">Aucune liaison pour ce monde. Construisez des capacités, puis choisissez une destination.</p>'}</section>`;
}
export function updateTradeEstimates(data,treasury){
  const buy=document.querySelector('#buy-capacities');
  if(buy){const q=Number(buy.elements.quantity.value),valid=Number.isInteger(q)&&q>0&&q<=data.prices.length;const cost=valid?data.prices.slice(0,q).reduce((a,b)=>a+Number(b),0):null;document.querySelector('#capacity-cost').textContent=cost===null?'—':money(cost);buy.querySelector('[type=submit]').disabled=!data.enabled||!valid||cost>Number(treasury);}
  const form=document.querySelector('#propose-trade');
  if(form){const d=data.destinations.find(x=>x.id===form.elements.target.value),q=Number(form.elements.quantity.value);document.querySelector('#route-estimate').textContent=d&&Number.isInteger(q)&&q>0?`${money(q*d.net_per_capacity)} / jour nets pour votre planète · entretien de distance : ${money(q*d.distance_cost)} / jour. Les bonus de l’autre monde sont calculés séparément.`:'Choisissez une destination pour estimer le revenu de votre planète.';}
}
